import { BadRequestException } from '@nestjs/common';
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import {
  PutObjectInput,
  StorageProvider,
  StorageProviderName,
  StoredObject,
} from '../storage.types';

/**
 * Development/test fallback. The object key is generated by UploadService,
 * never from a user filename, but the path is still contained explicitly.
 */
export class LocalStorageProvider implements StorageProvider {
  readonly name: StorageProviderName = 'local';
  private readonly root: string;

  constructor(rootDir?: string) {
    this.root = resolve(rootDir?.trim() || join(process.cwd(), 'uploads', 'storage'));
  }

  private pathFor(key: string): string {
    const target = resolve(this.root, key);
    if (target !== this.root && !target.startsWith(this.root + sep)) {
      throw new BadRequestException('invalid storage key');
    }
    return target;
  }

  async put(input: PutObjectInput): Promise<{ key: string }> {
    const target = this.pathFor(input.key);
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, input.body);
    return { key: input.key };
  }

  async get(key: string): Promise<StoredObject | null> {
    const target = this.pathFor(key);
    try {
      const body = await readFile(target);
      return { key, body, contentType: 'application/octet-stream' };
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathFor(key), { force: true });
  }
}
